arguments.workflowScript:
const results = await runs.all([
  {key:'inventory', agent:'scout', task:'In the current repository /Users/sofianebebert/workspace/sof-pi, inventory every packaged skill under skills/ (and any relevant skill-like files). For each, report path, frontmatter description, size, and a concise structural summary. Read-only reconnaissance; do not edit files.'},
  {key:'rubric', agent:'scout', task:'In the current repository /Users/sofianebebert/workspace/sof-pi, independently review all packaged skills under skills/ against these six rubrics: (1) starts from observed failures, (2) goals/constraints rather than procedures, (3) short and durable, (4) progressive disclosure, (5) living documentation/iteration, (6) selective creation. Give per-skill ratings with evidence and note uncertainty. Read-only; do not edit.'}
]);
return results.map((r,i)=>({lane:i, result:r}));

const result = await runs.run('repair', {agent:'worker', worktree:false, task:`Repair the incomplete weekly-planning refactor in /Users/sofianebebert/workspace/sof-pi. Current issue: SKILL.md links to references/friday-retro.md, but that file is missing. Use git show HEAD:skills/weekly-planning/SKILL.md as the source of truth to reconstruct the complete Friday Retro Variant behavior into skills/weekly-planning/references/friday-retro.md.

Preserve all Friday behavior from the original, including triggers, phase 1 snapshot/diff logic, all-project reporting, Daily Work calculations and carryover candidates, report format, one-at-a-time questions, Wheel of Life exact areas/rules, approval/write gate, in-place carryover policy, local note update behavior, and any important failure-derived rules. Keep it reference-focused and avoid duplicating the compact SKILL.md unnecessarily. Ensure relative links are correct.

Then inspect the refactor for omissions or broken links. Run a script/check that every markdown link in skills/weekly-planning/SKILL.md and its references resolves. Run git diff --check and report changed files, line counts, and validation. Do not modify unrelated skills or commit.`, acceptance:{level:'checked',evidence:['changed-files','commands-run','validation-output','diff-summary']}});
return result;

const results = await runs.all([
  {key:'writer', agent:'worker', worktree:false, task:`Create skills/README.md in /Users/sofianebebert/workspace/sof-pi. It should capture the key principles for writing good pi skills, based on the article takeaways and the actual refactors in this repository. Write practical guidance for this package's maintainers, including: start from observed agent failures; encode goals, constraints, and non-obvious context rather than exhaustive procedures; keep the always-loaded SKILL.md short and durable; use progressive disclosure with references; make skills living documentation with an explicit update loop; create skills selectively; preserve safety/approval/verification gates where relevant; distinguish principles from volatile command-level detail; and explain a useful review checklist. Mention examples from this repo (weekly-planning, tldraw-offline, database-query, exe-dev/fly-io/stripe-projects, write-like-me) without inventing facts. Keep it concise, clear, and actionable. Do not modify other files and do not commit. Validate Markdown basics and report the file and line count.`},
  {key:'reviewer', agent:'reviewer', worktree:false, task:`Review the request to create skills/README.md in /Users/sofianebebert/workspace/sof-pi. Inspect the existing skill files and repository conventions, then report what content the README must include to accurately capture good-skill principles from the article and this repo. Do not edit files. Flag omissions, misleading advice, or contradictions to existing skills. Provide a concise review checklist for validating the eventual file.`}
]);
return results.map((r,i)=>({lane:i, result:r}));
